func integerReplacement(n int) int {
	ans := 0
	for n != 1 {
		if (n & 1) == 0 {
			n >>= 1
		} else if n != 3 && (n&3) == 3 {
			n++
		} else {
			n--
		}
		ans++
	}
	return ans
}

class Solution(object):
    def integerReplacement(self, n):
        """
        :type n: int
        :rtype: int
        """
        self.d = {}
        return self._dfs(n)

    def _dfs(self, n):
        if n == 1:
            return 0
        if n in self.d:
            return self.d[n]
        if n % 2 == 0:
            ans = self._dfs(n / 2)
        else:
            ans = min(self._dfs(n + 1), self._dfs(n - 1))
        self.d[n] = ans + 1
        return ans + 1
